# Repository Guidelines

## Project Structure & Module Organization

This workspace is currently empty apart from this guide and has not been initialized as a Git repository. No source, test, or asset directories exist yet. When introducing the first implementation, document its entry points and directory responsibilities in a root `README.md`. Update this guide to reflect the actual layout; directory names such as `src/`, `tests/`, and `assets/` are examples, not established conventions.

## Build, Test, and Development Commands

No package manifest, build system, or development scripts are currently configured. There are no verified build, test, or local run commands. When adding a toolchain, document the exact installation, development, build, and validation commands here, including required runtime versions. Verify each command before presenting it as supported.

## Coding Style & Naming Conventions

No programming language, indentation standard, formatter, or linter has been selected. Establish these conventions alongside the first source files and record them in the relevant configuration. Follow those settings consistently in subsequent contributions.

## Testing Guidelines

No test framework or coverage threshold is configured. Introduce tests with executable code and document their location, naming pattern, and invocation. Describe checks actually performed and identify validation that remains unavailable.

## Commit & Pull Request Guidelines

Git history and pull request templates are unavailable, so no existing commit convention can be inferred. Once collaboration begins, use descriptive commit subjects and explain each proposed change, its purpose, and validation in the pull request. Link relevant issues when available; include screenshots for visible interface changes.
import type { SchoolConfig } from "./src/lib/school";

const config: SchoolConfig = {
	name: "My School",
	description: "An interactive course about your subject.",
	adjectives: [
		"bright",
		"clever",
		"cosmic",
		"curious",
		"eager",
		"golden",
		"keen",
		"mighty",
		"nimble",
		"radiant",
		"sharp",
		"steady",
	],
	nouns: [
		"builder",
		"explorer",
		"learner",
		"maker",
		"pioneer",
		"scholar",
		"seeker",
		"student",
		"thinker",
		"tinkerer",
		"traveler",
		"wizard",
	],
	colors: [
		"red",
		"orange",
		"amber",
		"yellow",
		"lime",
		"green",
		"emerald",
		"teal",
		"cyan",
		"sky",
		"blue",
		"indigo",
		"violet",
		"purple",
		"fuchsia",
		"pink",
		"rose",
		"slate",
	],
	profileFields: {
		learningStyle: {
			question: "How do you prefer to learn?",
			type: "single",
			options: [
				{
					value: "concepts-first",
					label: "Explain concepts first",
					description:
						"Understand the concept, then see practical applications",
				},
				{
					value: "hands-on",
					label: "Jump into hands-on exploration",
					description: "Start doing things, learn concepts as they come up",
				},
				{
					value: "examples",
					label: "Show me examples",
					description: "See concrete examples first, then infer the patterns",
				},
			],
			adaptation: {
				"concepts-first":
					"Explain the concept, then show the practical application.",
				"hands-on":
					"Jump straight to doing things, explain as concepts come up.",
				examples:
					"Lead with concrete examples, let the student infer the pattern.",
			},
		},
		depthPreference: {
			question: "How much detail do you want?",
			type: "single",
			options: [
				{
					value: "brief",
					label: "Keep it brief",
					description: "Short answers, get to the point",
				},
				{
					value: "some-context",
					label: "Some context is nice",
					description: "Normal explanations with some background",
				},
				{
					value: "all-details",
					label: "Give me all the details",
					description: "Thorough explanations, cover edge cases and rationale",
				},
			],
			adaptation: {
				brief: "Short answers. Get to the point. Minimal tangents.",
				"some-context": "Normal explanations with some background.",
				"all-details": "Thorough explanations. Cover edge cases and rationale.",
			},
		},
	},
	support: {
		issues: "https://github.com/your-org/your-school/issues",
	},
};

export default config;
{
  "name": "school-template",
  "type": "module",
  "version": "0.0.1",
  "private": true,
  "description": "Template for building interactive, agent-driven schools on any topic",
  "license": "Apache-2.0",
  "homepage": "https://github.com/opencodeschool/school-template",
  "repository": {
    "type": "git",
    "url": "https://github.com/opencodeschool/school-template.git"
  },
  "scripts": {
    "dev": "astro dev",
    "build": "astro build",
    "preview": "astro preview",
    "astro": "astro"
  },
  "dependencies": {
    "@astrojs/cloudflare": "^13.1.1",
    "@astrojs/mdx": "^5.0.0",
    "@fontsource/inter": "^5.2.8",
    "@fontsource/jetbrains-mono": "^5.2.8",
    "astro": "^6.0.4",
    "rehype-autolink-headings": "^7.1.0",
    "rehype-slug": "^6.0.0"
  },
  "devDependencies": {
    "@biomejs/biome": "^2.4.7",
    "@cloudflare/workers-types": "^4.20260313.1",
    "@tailwindcss/typography": "^0.5.19",
    "@tailwindcss/vite": "^4.2.1",
    "tailwindcss": "^4.2.1",
    "vitest": "^4.1.0",
    "wrangler": "^4.73.0"
  }
}
// Copyright (c) 2026 Cloudflare, Inc.
// Licensed under the Apache 2.0 license found in the LICENSE file or at:
//     https://opensource.org/licenses/Apache-2.0

import { defineCollection, z } from "astro:content";
import { glob } from "astro/loaders";

const lessons = defineCollection({
	loader: glob({ pattern: "**/*.{md,mdx}", base: "src/content/lessons" }),
	schema: z.object({
		title: z.string(),
		slug: z.string(),
		description: z.string(),
		order: z.number(),
		quiz: z.boolean(),
		agentOnly: z.boolean().default(false),
		agentInstructions: z.string(),
	}),
});

const exercises = defineCollection({
	loader: glob({ pattern: "**/*.{md,mdx}", base: "src/content/exercises" }),
	schema: z.object({
		title: z.string(),
		slug: z.string(),
		description: z.string(),
		order: z.number(),
		agentInstructions: z.string(),
	}),
});

export const collections = { lessons, exercises };
