cd schools/react && node --input-type=module <<'JS'
import fs from 'node:fs';
import assert from 'node:assert/strict';
import yaml from 'js-yaml';
import { transform } from 'esbuild';
import { createMarkdownProcessor } from '@astrojs/markdown-remark';
const processor = await createMarkdownProcessor({ syntaxHighlight: false });
const names = fs.readdirSync('src/content/lessons').filter(n=>n.endsWith('.md')).sort();
assert.equal(names.length,5);
const slugs = new Set();
let codeCount=0;
for (const [i,name] of names.entries()) {
  const text = fs.readFileSync(`src/content/lessons/${name}`,'utf8');
  const match=text.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/);
  assert.ok(match,name);
  const data=yaml.load(match[1]);
  for (const key of ['title','slug','description','agentInstructions']) assert.equal(typeof data[key],'string');
  assert.equal(data.order,i+1); assert.equal(data.quiz,false); assert.equal(data.agentOnly,true);
  assert.match(data.slug,/^[a-z]+(?:-[a-z]+)*$/); assert.ok(!slugs.has(data.slug)); slugs.add(data.slug);
  assert.match(data.agentInstructions,/\{origin\}\/sources\//);
  assert.match(data.agentInstructions,/GET/); assert.match(data.agentInstructions,/PUT/);
  assert.match(data.agentInstructions, /"source":"agent"/);
  for (const section of ['Worked example','Common misconception','activity','Core questions','Completion criterion','Traceable sources']) {
    assert.ok(match[2].toLowerCase().includes(section.toLowerCase()), `${name}: ${section}`);
  }
  const html=await processor.render(match[2]);
  assert.ok(html.code.length>100);
  for (const code of match[2].matchAll(/```(jsx|js)\n([\s\S]*?)\n```/g)) {
    await transform(code[2],{loader:code[1],jsx:'automatic'}); codeCount++;
  }
  console.log(`PASS: ${name} YAML, metadata, Markdown, activity structure and code syntax`);
}
await processor.render(fs.readFileSync('COURSE.md','utf8'));
async function loadConfig(path) {
  const result=await transform(fs.readFileSync(path,'utf8'),{loader:'ts',format:'esm'});
  return (await import(`data:text/javascript;base64,${Buffer.from(result.code).toString('base64')}`)).default;
}
const config=await loadConfig('school.config.ts');
const template=await loadConfig('../../upstream/school-template/school.config.ts');
assert.equal(config.name,'React School');
assert.match(config.description,/Understand why React components rerender/);
for (const field of ['adjectives','nouns','colors','profileFields']) assert.deepEqual(config[field],template[field]);
console.log(`PASS: COURSE Markdown, ${codeCount} code fences parsed, config syntax, identity vocabulary and profile fields retained.`);
JS

