from pathlib import Path
root=Path('schools/react/src/content/lessons')
for p in root.glob('*.md'):
    s=p.read_text()
    s=s.replace('<p>', '<span>').replace('</p>', '</span>')
    if p.name.startswith('03-'):
        s=s.replace('PlainNote', 'BasicNote')
    p.write_text(s)
PY
cd schools/react && node --input-type=module <<'JS'
import fs from 'node:fs';
import assert from 'node:assert/strict';
import yaml from 'js-yaml';
import { transform } from 'esbuild';
import { createMarkdownProcessor } from '@astrojs/markdown-remark';
const proseModule=await transform(fs.readFileSync('src/lib/mdx-to-prose.ts','utf8'),{loader:'ts',format:'esm'});
const {mdxToProse}=await import(`data:text/javascript;base64,${Buffer.from(proseModule.code).toString('base64')}`);
const processor=await createMarkdownProcessor({syntaxHighlight:false});
const names=fs.readdirSync('src/content/lessons').filter(n=>n.endsWith('.md')).sort();
assert.equal(names.length,5);
const slugs=new Set();
let codeCount=0;
for (const [i,name] of names.entries()) {
  const text=fs.readFileSync(`src/content/lessons/${name}`,'utf8');
  const match=text.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/); assert.ok(match);
  const data=yaml.load(match[1]);
  assert.deepEqual(Object.keys(data).sort(),['title','slug','description','order','quiz','agentOnly','agentInstructions'].sort());
  for (const key of ['title','slug','description','agentInstructions']) assert.equal(typeof data[key],'string');
  assert.equal(data.order,i+1); assert.equal(data.quiz,false); assert.equal(data.agentOnly,true);
  assert.match(data.slug,/^[a-z]+(?:-[a-z]+)*$/); assert.ok(!slugs.has(data.slug)); slugs.add(data.slug);
  assert.match(data.agentInstructions,/\{origin\}\/sources\//); assert.match(data.agentInstructions,/GET/); assert.match(data.agentInstructions,/PUT/); assert.match(data.agentInstructions,/"source":"agent"/);
  for (const section of ['Worked example','Common misconception','activity','Core questions','Completion criterion','Traceable sources']) assert.ok(match[2].toLowerCase().includes(section.toLowerCase()));
  assert.equal(mdxToProse(match[2]),match[2].trim(),`${name}: API must preserve body and fenced examples`);
  const html=await processor.render(match[2]); assert.ok(html.code.length>100);
  for (const code of match[2].matchAll(/```(jsx|js)\n([\s\S]*?)\n```/g)) { await transform(code[2],{loader:code[1],jsx:'automatic'}); codeCount++; }
  console.log(`PASS: ${name}: metadata, Markdown, code syntax, and unchanged API prose`);
}
await processor.render(fs.readFileSync('COURSE.md','utf8'));
console.log(`PASS: five lessons, ${codeCount} parsed JS/JSX fences, COURSE rendered.`);
